__global__ void softmax(const float* logits, float* exponentials, float* probabilities, int n) {
  if (blockIdx.x != 0 || threadIdx.x != 0) {
    return;
  }
  float maxValue = logits[0];
  for (int i = 1; i < n; i++) {
    if (logits[i] > maxValue) {
      maxValue = logits[i];
    }
  }
  float total = 0.0f;
  for (int i = 0; i < n; i++) {
    exponentials[i] = expf(logits[i] - maxValue);
    total += exponentials[i];
  }
  for (int i = 0; i < n; i++) {
    probabilities[i] = exponentials[i] / total;
  }
}
